            section = sections.setdefault(line[1:-1].strip(), {})
            continue
        positions = [i for i in (line.find("="), line.find(":")) if i >= 0]
        if not positions:
            raise ParseError(lineno, f"invalid line: {line!r}")
        split = min(positions)
        name = line[:split].strip().lower()
        if not name:
            raise ParseError(lineno, "empty key")
        if section is None:
            raise ParseError(lineno, f"key {name!r} before any section")
        section[name] = line[split + 1 :].strip()
        key = name
    return _interpolate(sections)


def _interpolate(sections: dict[str, dict[str, str]]) -> dict[str, dict[str, str]]:
    done: dict[tuple[str, str], str] = {}
    active: set[tuple[str, str]] = set()

    def resolve(section: str, key: str) -> str:
        ref = (section, key)
        if ref in done:
            return done[ref]
        if ref in active:
            raise InterpolationError(f"cycle through key {key!r} in section {section!r}")
        active.add(ref)
        value = sections[section][key]
        parts = []
        i = 0
        while True:
            start = value.find("$", i)
            if start < 0:
                parts.append(value[i:])
                break
            parts.append(value[i:start])
            after = value[start + 1 : start + 2]
            end = value.find("}", start + 2) if after == "{" else -1
            if after == "$":
                parts.append("$")
                i = start + 2
            elif end < 0:
                parts.append("$")
                i = start + 1
            else:
                target, colon, name = value[start + 2 : end].rpartition(":")
                target = target.strip() if colon else section
                name = name.strip().lower()
                if target not in sections:
                    raise InterpolationError(f"no section {target!r}")
                if name not in sections[target]:
                    raise InterpolationError(f"no key {name!r} in section {target!r}")
                parts.append(resolve(target, name))
                i = end + 1
        active.discard(ref)
        done[ref] = "".join(parts)
        return done[ref]

    return {
        section: {key: resolve(section, key) for key in values}
        for section, values in sections.items()
    }

